import kotlin.math.*

const val EPS = 1e-9
const val PI = PI.toDouble()
const val INF = 1e10

data class Point(val x: Double, val y: Double) {
    operator fun plus(other: Point) = Point(x + other.x, y + other.y)
    operator fun minus(other: Point) = Point(x - other.x, y - other.y)
    operator fun times(k: Double) = Point(x * k, y * k)
    operator fun div(k: Double) = this * (1.0 / k)
    fun rot90() = Point(-y, x)
    fun mod() = hypot(x, y)
    fun mod2() = x * x + y * y
}

typealias Vec = Point

fun dot(a: Vec, b: Vec) = a.x * b.x + a.y * b.y
fun cross(a: Vec, b: Vec) = a.x * b.y - a.y * b.x
fun unit(v: Vec) = v / v.mod()
fun rotate(v: Vec, ang: Double): Vec {
    val ca = cos(ang)
    val sa = sin(ang)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)
}
fun projectOnLine(p: Point, a: Point, b: Point): Point {
    val ab = b - a
    val ap = p - a
    return a + unit(ab) * (dot(ab, ap) / ab.mod())
}
fun distToLine(p: Point, a: Point, b: Point) = (projectOnLine(p, a, b) - p).mod()

fun lineCircleIntersection(a: Point, b: Point, o: Point, r: Double): List<Point> {
    val t = projectOnLine(o, a, b)
    val ot = t - o
    val dotMod = ot.mod()
    if (dotMod - r > EPS) return emptyList()
    if (abs(dotMod - r) < EPS) return listOf(t)
    val lr = sqrt(max(0.0, r * r - dotMod * dotMod))
    val dirA = unit(a - t)
    val dirB = unit(b - t)
    return listOf(t + dirA * lr, t + dirB * lr)
}

fun tangentPoints(p: Point, o: Point, r: Double): List<Point> {
    val op = p - o
    val x2 = op.mod2()
    val d2 = x2 - r * r
    if (d2 < -EPS) return emptyList()
    if (r < EPS) return listOf(o, o)
    val d2Safe = max(0.0, d2)
    val q1 = o + op * (r * r / x2)
    val q2 = op.rot90() * (-r * sqrt(d2Safe) / x2)
    return listOf(q1 - q2, q1 + q2)
}

fun onSegment(p: Point, a: Point, b: Point): Boolean {
    if (abs(cross(b - a, p - a)) > EPS) return false
    if (p.x < min(a.x, b.x) - EPS || p.x > max(a.x, b.x) + EPS) return false
    if (p.y < min(a.y, b.y) - EPS || p.y > max(a.y, b.y) + EPS) return false
    return true
}

fun angleBetween(a: Vec, b: Vec): Double {
    val cosA = dot(a, b) / (a.mod() * b.mod())
    return acos(max(-1.0, min(1.0, cosA)))
}

fun main() {
    val input = System.`in`.bufferedReader()
    val output = System.out
    var line: String?
    while (true) {
        line = input.readLine()
        if (line == null) break
        val parts = line.trim().split("\\s+").filter { it.isNotEmpty() }.map { it.toDouble() }
        if (parts.size != 7) continue

        val p = Point(parts[0], parts[1])
        val vp = parts[2]
        val s = Point(parts[3], parts[4])
        val vs = parts[5]
        val r = parts[6]

        val lenOr = p.mod()
        var sita = acos(max(-1.0, min(1.0, p.x / lenOr)))
        if (p.y < 0) sita = -sita

        fun check(t: Double): Boolean {
            val ang = sita + t * vp / lenOr
            val e = Point(lenOr * cos(ang), lenOr * sin(ang))

            val intersections = lineCircleIntersection(s, e, Point(0.0, 0.0), r)
            val crossOnSeg = intersections.count { onSegment(it, s, e) }

            if (intersections.size != 2 || crossOnSeg != 2) {
                return vs * t >= (e - s).mod() - EPS
            }

            var tp1 = tangentPoints(s, Point(0.0, 0.0), r)
            if (distToLine(tp1[0], s, e) > distToLine(tp1[1], s, e)) {
                tp1 = tp1.reversed()
            }
            val l1 = (s - tp1[0]).mod()

            var tp2 = tangentPoints(e, Point(0.0, 0.0), r)
            if (distToLine(tp2[0], s, e) > distToLine(tp2[1], s, e)) {
                tp2 = tp2.reversed()
            }
            val l2 = (e - tp2[0]).mod()

            val alpha = angleBetween(tp1[0], tp2[0])
            return l1 + l2 + alpha * r <= vs * t + EPS
        }

        var left = 0.0
        var right = INF
        while (right - left > 1e-12) {
            val mid = (left + right) * 0.5
            if (check(mid)) right = mid else left = mid
        }
        println("%.9f".format(left))
    }
}

