    operator fun minus(other: Point) = Point(x - other.x, y - other.y)
    operator fun times(k: Double) = Point(x * k, y * k)
    operator fun div(k: Double) = this * (1.0 / k)
    operator fun unaryMinus() = Point(-x, -y)

    fun dot(other: Point): Double = x * other.x + y * other.y
    fun cross(other: Double): Double = x * other.y - y * other.x
    fun cross(other: Point): Double = x * other.y - y * other.x
    fun norm2(): Double = dot(this)
    fun norm(): Double = sqrt(norm2())
    fun unit(): Point = this / norm()
    fun rot90(): Point = Point(-y, x)
    fun rotate(angle: Double): Point {
        val ca = cos(angle)
        val sa = sin(angle)
        return Point(x * ca - y * sa, x * sa + y * ca)
    }
    fun distanceTo(other: Point): Double = (this - other).norm()
}

fun lineCircleIntersection(a: Point, b: Point, o: Point, r: Double): List<Point> {
    val ab = b - a
    val ao = o - a
    val t = a + ab.unit() * (ab.dot(ao) / ab.norm())
    val ot = t - o
    val d = ot.norm()
    if (d - r > EPS) return emptyList()
    if (abs(d - r) < EPS) return listOf(t)
    val l = sqrt(max(0.0, r * r - d * d))
    val dir = ab.unit()
    return listOf(t + dir * l, t - dir * l)
}

fun pointTangentCircle(p: Point, o: Point, r: Double): List<Point> {
    val op = p - o
    val x2 = op.norm2()
    val d2 = x2 - r * r
    if (d2 < -EPS) return emptyList()
    if (r <= EPS) return listOf(o, o)
    val d2Safe = max(0.0, d2)
    val q1 = o + op * (r * r / x2)
    val q2 = op.rot90() * (-r * sqrt(d2Safe) / x2)
    return listOf(q1 - q2, q1 + q2)
}

fun onSegment(p: Point, a: Point, b: Point): Boolean {
    if (abs((b - a).cross(p - a)) > EPS) return false
    if (p.x < min(a.x, b.x) - EPS || p.x > max(a.x, b.x) + EPS) return false
    if (p.y < min(a.y, b.y) - EPS || p.y > max(a.y, b.y) + EPS) return false
    return true
}

fun pointLineDistance(p: Point, a: Point, b: Point): Double {
    val ab = b - a
    val ap = p - a
    val t = a + ab.unit() * (ab.dot(ap) / ab.norm())
    return (p - t).norm()
}

fun angleBetween(v1: Point, v2: Point): Double {
    val cosA = v1.dot(v2) / v1.norm() / v2.norm()
    return acos(max(-1.0, min(1.0, cosA)))
